import bpy,sys,pathlib,numpy as np,json,ast,subprocess
D=pathlib.Path(sys.argv[sys.argv.index('--')+1]).resolve();sys.path.insert(0,str(D));import exr_io
channels=exr_io.read(D/'images/seed-11-front-baseline.exr');rgb=lambda n:np.stack([channels['ViewLayer.'+n+'.'+c] for c in 'RGB'],-1).astype(float)
c=rgb('Combined');r=(rgb('DiffDir')+rgb('DiffInd'))*rgb('DiffCol')+(rgb('GlossDir')+rgb('GlossInd'))*rgb('GlossCol')+(rgb('TransDir')+rgb('TransInd'))*rgb('TransCol')+rgb('VolumeDir')+rgb('VolumeInd')+rgb('Emit')+rgb('Env');err=r-c;bad=abs(err)>2e-5+5e-6*abs(c)
report={'maxAbs':float(abs(err).max()),'RMSE':float(np.sqrt(np.mean(err**2))),'sumAbs':float(abs(err).sum()),'violatingComponents':int(bad.sum()),'violatingPixels':int(bad.any(-1).sum()),'examples':[{'y':int(y),'x':int(x),'channel':int(k),'combined':float(c[y,x,k]),'reconstructed':float(r[y,x,k]),'error':float(err[y,x,k])} for y,x,k in np.argwhere(bad)],'nonzeroPasses':{n:float(abs(rgb(n)).max()) for n in ['DiffDir','DiffInd','DiffCol','GlossDir','GlossInd','GlossCol','TransDir','TransInd','TransCol','VolumeDir','VolumeInd','Emit','Env']}}
(D/'recomposition-investigation.json').write_text(json.dumps(report,indent=2));print(report)
