for name,a in [('combined',c),('reconstructed',r)]:
 out=D/'images'/('diagnostic-'+name+'.png');ns['display'](sc,a,out);subprocess.run(['python3',str(D/'png_compare.py'),str(D/'images/seed-11-front-baseline-combined.png'),str(out),str(D/('diagnostic-'+name+'-PNG-difference.json'))],check=False)
